"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[5946],{55946:e=>{e.exports=JSON.parse('{"slug":"inflyaciya-ssha-pce-avgust-stavka-frs","locale":"es","title":"La inflaci\xf3n de agosto en Estados Unidos queda bajo lo previsto, en parte por una revisi\xf3n estad\xedstica","description":"La inflaci\xf3n estadounidense fue del 3,4%, frente al 3,7% previsto. La Fed no plantea recortes; el mercado reduce al 35% la probabilidad de subir en octubre. Qu\xe9 parte se debe a revisar la estad\xedstica.","blocks":[{"id":"b001","kind":"paragraph","text":"Comercio public\xf3 el 30 de septiembre de 2026 la inflaci\xf3n estadounidense de agosto. Los precios crecieron un 3,4% interanual frente al 3,7% esperado. Sin alimentos y energ\xeda, m\xe1s vol\xe1tiles, fue del 3%, frente al 3,3% previsto. Es el \xedndice PCE, principal referencia de la Reserva Federal, el banco central estadounidense, cuya meta es el 2%."},{"id":"b002","kind":"paragraph","text":"El dato cambi\xf3 las expectativas. En septiembre, la Fed subi\xf3 el tipo por primera vez desde 2023, al 3,75–4%. La probabilidad de otra subida el 27–28 de octubre baj\xf3 de alrededor del 45% al 35%. No supone volver al dinero barato: la Fed no planea ni promete recortes. El mercado solo est\xe1 menos convencido de otra subida."},{"id":"b003","kind":"paragraph","text":"Pero la desaceleraci\xf3n subyacente procede de la estad\xedstica. La Oficina de An\xe1lisis Econ\xf3mico cambi\xf3 el c\xe1lculo de servicios jur\xeddicos, programas inform\xe1ticos y gesti\xf3n de inversiones, revisando datos desde 2021. Es una tienda que cambia la b\xe1scula y recalcula recibos: parece m\xe1s barato aunque el cliente pague igual. Esa revisi\xf3n hist\xf3rica redujo la inflaci\xf3n de julio sin alimentos y energ\xeda en 0,36 puntos, de cerca del 3,3% al 3%. Por tanto, en agosto no cay\xf3: se mantuvo."},{"id":"b004","kind":"paragraph","text":"La econom\xeda no se frena. El PIB del segundo trimestre de 2026 se revis\xf3 del 1,5% al 2,2%, y el gasto de agosto creci\xf3 al mayor ritmo del a\xf1o. Neel Kashkari afirm\xf3 que una inflaci\xf3n cercana al 3% sigue siendo demasiado alta y lleva m\xe1s de 5 a\xf1os por encima de la meta. Los nuevos datos apenas alteran ese diagn\xf3stico."},{"id":"b005","kind":"paragraph","text":"Por eso no se abarata el cr\xe9dito. La rentabilidad del bono p\xfablico estadounidense a 10 a\xf1os subi\xf3 a cerca del 5,3%, referencia de las hipotecas. Para Rusia, el canal es un d\xf3lar que resiste: los bonos pagan m\xe1s del 5% y la financiaci\xf3n en d\xf3lares sigue cara. El tipo oficial del 1 de octubre es 83,56 rublos por d\xf3lar, 87 kopeks menos que el d\xeda anterior. El rublo mejor\xf3 por factores internos: ventas de divisas de exportadores al cierre trimestral y menor actividad importadora antes de los festivos chinos."},{"id":"b006","kind":"paragraph","text":"No sabemos el efecto del encarecimiento del combustible de septiembre por la guerra con Ir\xe1n, a\xfan ausente en agosto. El pr\xf3ximo informe podr\xeda devolver la conversaci\xf3n a las subidas. Vender d\xf3lares por la menor inflaci\xf3n es confiar en una cifra explicada en gran parte por una revisi\xf3n. Comprarlos apostando a m\xe1s subidas es confiar en un informe que nadie ha visto."},{"id":"b007","kind":"heading","text":"\xbfCu\xe1l fue la inflaci\xf3n estadounidense de agosto de 2026?"},{"id":"b008","kind":"paragraph","text":"Un 3,4% anual seg\xfan el PCE, referencia de la Fed, frente al 3,7% previsto. Sin alimentos ni energ\xeda, un 3%, frente al 3,3% esperado. La meta es el 2%."},{"id":"b009","kind":"heading","text":"\xbfSubir\xe1 la Fed los tipos en octubre de 2026?"},{"id":"b010","kind":"paragraph","text":"Tras agosto, el mercado asigna alrededor del 35%, frente al 45% anterior. El tipo actual es del 3,75–4%; la decisi\xf3n llega el 27–28 de octubre."},{"id":"b011","kind":"heading","text":"\xbfPor qu\xe9 la inflaci\xf3n qued\xf3 bajo lo previsto?"},{"id":"b012","kind":"paragraph","text":"En parte por la metodolog\xeda: se revisaron servicios jur\xeddicos, programas y gesti\xf3n de inversiones desde 2021. La inflaci\xf3n de julio sin alimentos y energ\xeda baj\xf3 0,36 puntos tras el cambio, aproximadamente del 3,3% al 3%."}],"sources":[{"label":"La referencia de la Fed muestra inflaci\xf3n subyacente del 3.0% en agosto","url":"https://www.cnbc.com/2026/09/30/feds-preferred-gauge-showed-core-inflation-at-3point0percent-in-august-much-lighter-than-expected.html"},{"label":"Entrevista con Neel Kashkari, presidente de la Fed de Minneapolis","url":"https://www.cnbc.com/2026/09/30/watch-minneapolis-fed-president-neel-kashkari.html"},{"label":"La menor inflaci\xf3n reduce la probabilidad de otra subida de la Fed","url":"https://www.theguardian.com/business/2026/sep/30/inflation-report-interest-rates-fed"},{"label":"El PCE baja al 3.4% y debilita el argumento para otra subida","url":"https://finance.yahoo.com/economy/policy/article/pce-inflation-eases-to-34--cooling-the-case-for-another-fed-rate-hike-125513195.html"},{"label":"Revisi\xf3n a la baja del \xedndice PCE","url":"https://finance.yahoo.com/economy/articles/pce-price-index-revised-down-123741659.html"},{"label":"La referencia preferida de la Fed queda por debajo de lo esperado","url":"https://finance.yahoo.com/economy/articles/feds-preferred-inflation-metric-came-163426036.html"},{"label":"Baja el indicador de inflaci\xf3n preferido de la Fed","url":"https://finance.yahoo.com/economy/policy/articles/feds-preferred-inflation-gauge-declined-174601544.html"},{"label":"La inflaci\xf3n preferida de la Fed crece un 3.4%","url":"https://finance.yahoo.com/economy/policy/articles/fed-preferred-measure-inflation-rose-124249351.html"},{"label":"El oro se estabiliza tras los menores datos de inflaci\xf3n","url":"https://finance.yahoo.com/markets/commodities/articles/gold-steady-softer-inflation-data-000816044.html"},{"label":"Kashkari afirma que la inflaci\xf3n supera el efecto del petr\xf3leo","url":"https://finance.yahoo.com/economy/policy/articles/feds-kashkari-says-inflation-goes-150738609.html"},{"label":"El tipo oficial del d\xf3lar cae por debajo de 84 rublos","url":"https://www.vedomosti.ru/finance/news/2026/09/30/1233185-kurs-opustilsya"},{"label":"D\xf3lar, euro y yuan al 1 de octubre de 2026: por qu\xe9 se fortalece el rublo","url":"https://www.vbr.ru/novosti/kursy-valyut/2026/09/30/kurs-valut-na-1-oktyabrya/"},{"label":"Calendario e informaci\xf3n de reuniones","url":"https://www.federalreserve.gov/monetarypolicy/fomccalendars.htm"}],"sourceBodySha256":"1145a94c8144e6d38a235e40e919942738f6348f62bad69c60f81ff17dc4c1a0"}')}}]);